INSERT INTO sat_questions (question_id, external_id, vault_id, disclosed_item_id, source, program, test_type, test_type_desc, domain, primary_class_cd, skill_cd, skill_desc, difficulty, score_band_range_cd, question_type, stimulus_html, stem_html, answer_options, correct_answer, answer_keys, rationale_html, correct_answer_extracted_from_rationale, image_count, parent_template_name, parent_template_id, template_cluster_id, template_cluster_name, origin, position, answer_style, section, raw_payload, created_date, updated_date) VALUES
    ($SATQ$1993561d$SATQ$, $SATQ$baf1c184-aaa3-416b-ac7d-232d0c6ccc89$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 2, $SATQ$Math$SATQ$, $SATQ$Algebra$SATQ$, $SATQ$H$SATQ$, $SATQ$H.B.$SATQ$, $SATQ$Linear functions$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, NULL, $SATQ$<p style="text-align: left;">For the linear function&nbsp;<math alttext="f"><mi>f</mi></math>, the graph of&nbsp;<math alttext="y equals f left parenthesis x right parenthesis"><mi>y</mi><mo>=</mo><mi>f</mi><mfenced><mi>x</mi></mfenced></math> in the <em>xy</em>-plane has a slope of&nbsp;<math alttext="one fourth"><mfrac><mn>1</mn><mn>4</mn></mfrac></math> and passes through the point&nbsp;<math alttext="left parenthesis 0 comma 5 right parenthesis"><mfenced><mrow><mn>0</mn><mo>,</mo><mn>5</mn></mrow></mfenced></math>. Which equation defines&nbsp;<math alttext="f"><mi>f</mi></math>?</p>$SATQ$, $SATQ$[{"id":"d417427f-2e39-43b4-8aff-28728ed02c62","content":"<p><math alttext=\"f left parenthesis x right parenthesis equals one fourth x plus 5\"><mi>f</mi><mfenced><mi>x</mi></mfenced><mo>=</mo><mfrac><mn>1</mn><mrow><mn>4</mn></mrow></mfrac><mi>x</mi><mo>+</mo><mrow><mn>5</mn></mrow></math></p>"},{"id":"a053a1db-5344-43b8-959e-911218677271","content":"<p><math alttext=\"f left parenthesis x right parenthesis equals one fourth x plus one fifth\"><mi>f</mi><mfenced><mi>x</mi></mfenced><mo>=</mo><mfrac><mn>1</mn><mrow><mn>4</mn></mrow></mfrac><mi>x</mi><mo>+</mo><mfrac><mn>1</mn><mrow><mn>5</mn></mrow></mfrac></math></p>"},{"id":"5267e1f0-14d7-48a2-9c85-4b5e4bee24bd","content":"<p><math alttext=\"f left parenthesis x right parenthesis equals one fourth x minus five fourths\"><mi>f</mi><mo>(</mo><mi>x</mi><mo>)</mo><mo>=</mo><mfrac><mn>1</mn><mrow><mn>4</mn></mrow></mfrac><mi>x</mi><mo>-</mo><mfrac><mrow><mn>5</mn></mrow><mrow><mn>4</mn></mrow></mfrac></math></p>"},{"id":"56f41e96-2a23-480e-ad8a-71b6a975f40d","content":"<p><math alttext=\"f left parenthesis x right parenthesis equals one fourth x minus 5\"><mi>f</mi><mfenced><mi>x</mi></mfenced><mo>=</mo><mfrac><mn>1</mn><mrow><mn>4</mn></mrow></mfrac><mi>x</mi><mo>-</mo><mrow><mn>5</mn></mrow></math></p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["d417427f-2e39-43b4-8aff-28728ed02c62"]$SATQ$::jsonb, $SATQ$<p style="text-align: left;">Choice A is correct. An equation that defines a linear function <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="f"><mi>f</mi></math> can be written in the form <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="f left parenthesis x right parenthesis equals m x plus b"><mi>f</mi><mo>(</mo><mi>x</mi><mo>)</mo><mo>=</mo><mi>m</mi><mi>x</mi><mo>+</mo><mi>b</mi></math>, where <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="m"><mi>m</mi></math> is the slope of the graph of <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="y equals f left parenthesis x right parenthesis"><mi>y</mi><mo>=</mo><mi>f</mi><mo>(</mo><mi>x</mi><mo>)</mo></math> in the <em>xy</em>-plane and <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="left parenthesis 0 comma b right parenthesis"><mo>(</mo><mn>0</mn><mo>,</mo><mi>b</mi><mo>)</mo></math> is the <em>y</em>-intercept of the graph. It’s given that for the linear function <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="f"><mi>f</mi></math>, the graph of <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="y equals f left parenthesis x right parenthesis"><mi>y</mi><mo>=</mo><mi>f</mi><mo>(</mo><mi>x</mi><mo>)</mo></math> in the <em>xy</em>-plane has a slope of <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="one fourth"><mfrac><mn>1</mn><mn>4</mn></mfrac></math>. Therefore, <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="m equals one fourth"><mi>m</mi><mo>=</mo><mfrac><mn>1</mn><mn>4</mn></mfrac></math>. It’s also given that the graph of <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="y equals f left parenthesis x right parenthesis"><mi>y</mi><mo>=</mo><mi>f</mi><mo>(</mo><mi>x</mi><mo>)</mo></math> passes through the point <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="left parenthesis 0 comma 5 right parenthesis"><mo>(</mo><mn>0</mn><mo>,</mo><mn>5</mn><mo>)</mo></math>. Therefore, the <em>y</em>-intercept of the graph is <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="left parenthesis 0 comma 5 right parenthesis"><mo>(</mo><mn>0</mn><mo>,</mo><mn>5</mn><mo>)</mo></math>, and it follows that <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="b equals 5"><mi>b</mi><mo>=</mo><mn>5</mn></math>. Substituting <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="one fourth"><mfrac><mn>1</mn><mn>4</mn></mfrac></math> for <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="m"><mi>m</mi></math> and <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="5"><mn>5</mn></math> for <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="b"><mi>b</mi></math> in the equation <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="f left parenthesis x right parenthesis equals m x plus b"><mi>f</mi><mo>(</mo><mi>x</mi><mo>)</mo><mo>=</mo><mi>m</mi><mi>x</mi><mo>+</mo><mi>b</mi></math> yields <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="f left parenthesis x right parenthesis equals one fourth x plus 5"><mi>f</mi><mo>(</mo><mi>x</mi><mo>)</mo><mo>=</mo><mfrac><mn>1</mn><mn>4</mn></mfrac><mi>x</mi><mo>+</mo><mn>5</mn></math>.</p>
<p style="text-align: left;">Choice B is incorrect. This equation defines a function whose graph has a <em>y</em>-intercept of <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="left parenthesis 0 comma one fifth right parenthesis"><mo>(</mo><mn>0</mn><mo>,</mo><mfrac><mn>1</mn><mn>5</mn></mfrac><mo>)</mo></math>, not <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="left parenthesis 0 comma 5 right parenthesis"><mo>(</mo><mn>0</mn><mo>,</mo><mn>5</mn><mo>)</mo></math>.</p>
<p style="text-align: left;">Choice C is incorrect. This equation defines a function whose graph has a <em>y</em>-intercept of <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="left parenthesis 0 comma negative five fourths right parenthesis"><mo>(</mo><mn>0</mn><mo>,</mo><mo>-</mo><mfrac><mn>5</mn><mn>4</mn></mfrac><mo>)</mo></math>, not <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="left parenthesis 0 comma 5 right parenthesis"><mo>(</mo><mn>0</mn><mo>,</mo><mn>5</mn><mo>)</mo></math>.</p>
<p style="text-align: left;">Choice D is incorrect. This equation defines a function whose graph has a <em>y</em>-intercept of <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="left parenthesis 0 comma negative 5 right parenthesis"><mo>(</mo><mn>0</mn><mo>,</mo><mo>-</mo><mn>5</mn><mo>)</mo></math>, not <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="left parenthesis 0 comma 5 right parenthesis"><mo>(</mo><mn>0</mn><mo>,</mo><mn>5</mn><mo>)</mo></math>.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"1993561d","external_id":"baf1c184-aaa3-416b-ac7d-232d0c6ccc89","disclosed_item_id":null,"source":"qbank","vaultid":null,"uId":"fc2fb36d-043b-4275-9c91-af6d35c1ad93","program":"SAT","test_type":2,"test_type_desc":"Math","primary_class_cd":"H","domain":"Algebra","skill_cd":"H.B.","skill_desc":"Linear functions","difficulty":"E","score_band_range_cd":2,"type":"mcq","stimulus":null,"stem":"<p style=\"text-align: left;\">For the linear function&nbsp;<math alttext=\"f\"><mi>f</mi></math>, the graph of&nbsp;<math alttext=\"y equals f left parenthesis x right parenthesis\"><mi>y</mi><mo>=</mo><mi>f</mi><mfenced><mi>x</mi></mfenced></math> in the <em>xy</em>-plane has a slope of&nbsp;<math alttext=\"one fourth\"><mfrac><mn>1</mn><mn>4</mn></mfrac></math> and passes through the point&nbsp;<math alttext=\"left parenthesis 0 comma 5 right parenthesis\"><mfenced><mrow><mn>0</mn><mo>,</mo><mn>5</mn></mrow></mfenced></math>. Which equation defines&nbsp;<math alttext=\"f\"><mi>f</mi></math>?</p>","answerOptions":[{"id":"d417427f-2e39-43b4-8aff-28728ed02c62","content":"<p><math alttext=\"f left parenthesis x right parenthesis equals one fourth x plus 5\"><mi>f</mi><mfenced><mi>x</mi></mfenced><mo>=</mo><mfrac><mn>1</mn><mrow><mn>4</mn></mrow></mfrac><mi>x</mi><mo>+</mo><mrow><mn>5</mn></mrow></math></p>"},{"id":"a053a1db-5344-43b8-959e-911218677271","content":"<p><math alttext=\"f left parenthesis x right parenthesis equals one fourth x plus one fifth\"><mi>f</mi><mfenced><mi>x</mi></mfenced><mo>=</mo><mfrac><mn>1</mn><mrow><mn>4</mn></mrow></mfrac><mi>x</mi><mo>+</mo><mfrac><mn>1</mn><mrow><mn>5</mn></mrow></mfrac></math></p>"},{"id":"5267e1f0-14d7-48a2-9c85-4b5e4bee24bd","content":"<p><math alttext=\"f left parenthesis x right parenthesis equals one fourth x minus five fourths\"><mi>f</mi><mo>(</mo><mi>x</mi><mo>)</mo><mo>=</mo><mfrac><mn>1</mn><mrow><mn>4</mn></mrow></mfrac><mi>x</mi><mo>-</mo><mfrac><mrow><mn>5</mn></mrow><mrow><mn>4</mn></mrow></mfrac></math></p>"},{"id":"56f41e96-2a23-480e-ad8a-71b6a975f40d","content":"<p><math alttext=\"f left parenthesis x right parenthesis equals one fourth x minus 5\"><mi>f</mi><mfenced><mi>x</mi></mfenced><mo>=</mo><mfrac><mn>1</mn><mrow><mn>4</mn></mrow></mfrac><mi>x</mi><mo>-</mo><mrow><mn>5</mn></mrow></math></p>"}],"keys":["d417427f-2e39-43b4-8aff-28728ed02c62"],"correct_answer":["A"],"rationale":"<p style=\"text-align: left;\">Choice A is correct. An equation that defines a linear function <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"f\"><mi>f</mi></math> can be written in the form <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"f left parenthesis x right parenthesis equals m x plus b\"><mi>f</mi><mo>(</mo><mi>x</mi><mo>)</mo><mo>=</mo><mi>m</mi><mi>x</mi><mo>+</mo><mi>b</mi></math>, where <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"m\"><mi>m</mi></math> is the slope of the graph of <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"y equals f left parenthesis x right parenthesis\"><mi>y</mi><mo>=</mo><mi>f</mi><mo>(</mo><mi>x</mi><mo>)</mo></math> in the <em>xy</em>-plane and <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"left parenthesis 0 comma b right parenthesis\"><mo>(</mo><mn>0</mn><mo>,</mo><mi>b</mi><mo>)</mo></math> is the <em>y</em>-intercept of the graph. It’s given that for the linear function <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"f\">