8125 \nQ 11.53125 32.328125 10.9375 33.109375 \nQ 10.359375 33.890625 10.359375 34.28125 \nQ 10.640625 35.9375 13.953125 39.203125 \nQ 17.28125 42.484375 20.3125 42.484375 \nz\n\" id=\"CrimsonText-Italic-120\"></path>\n     </defs>\n     <g transform=\"translate(277.443926 244.798528)scale(0.15 -0.15)\">\n      <use xlink:href=\"#CrimsonText-Italic-120\"></use>\n     </g>\n    </g>\n   </g>\n   <g id=\"line2d_1\">\n    <path clip-path=\"url(#pcfd5fbe2c1)\" d=\"M 63.03256 69.188665 \nL 262.729982 241.848163 \nL 262.729982 241.848163 \n\" style=\"fill:none;stroke:#000000;stroke-linecap:square;stroke-width:2.3;\"></path>\n   </g>\n  </g>\n </g>\n <defs>\n  <clipPath id=\"pcfd5fbe2c1\">\n   <rect height=\"260.82\" width=\"270.55209\" x=\"22.675986\" y=\"7.2\"></rect>\n  </clipPath>\n </defs>\n</svg>\n<div role=\"region\" aria-label=\"Long description for graph of a line\" class=\"sr-only\"><ul><li>The line slants gradually down from left to right.</li>\n<li>The line passes through the following approximate points:<br>\n<ul>\n<li>(0 comma 136)</li>\n<li>(158 comma 0)</li>\n</ul>\n</li>\n</ul></div></figure></p>\n<p style=\"text-align: left;\">A certain open star cluster contains M-type stars and K-type stars. The estimated total mass of M-type and K-type stars in this open star cluster is <math alttext=\"127,882 quettagrams\"><mrow><mn>127,882</mn></mrow><mo>&#160;</mo><mtext>quettagrams</mtext></math>. The graph shown models the possible combinations of the number of M-type stars, <math alttext=\"x\"><mi>x</mi>\n</math>, and K-type stars, <math alttext=\"y\"><mi>y</mi>\n</math>, that could be in this open star cluster if all the M-type stars have the same estimated mass and all the K-type stars have the same estimated mass. Based on the graph, which of the following is closest to the estimated mass, in quettagrams, of each M-type star in this cluster?</p>","answerOptions":[{"id":"765b9918-d1b6-4fa2-b0a5-42fc28ef7ede","content":"<p><math alttext=\"811\"><mn>811</mn>\n</math></p>"},{"id":"73aaae1d-508b-423b-b76a-65d5c05df6cb","content":"<p><math alttext=\"938\"><mn>938</mn>\n</math></p>"},{"id":"03f69d84-a2f8-4fd3-a67a-6e230a6695f7","content":"<p><math alttext=\"51,904\"><mn>51,904</mn>\n</math></p>"},{"id":"a6a03714-8c91-4cc7-85f9-de51bd3439c5","content":"<p><math alttext=\"75,978\"><mn>75,978</mn>\n</math></p>"}],"keys":["765b9918-d1b6-4fa2-b0a5-42fc28ef7ede"],"correct_answer":["A"],"rationale":"<p>Choice A is correct. The <em>x</em>-intercept of the graph shown represents the situation in which the cluster contains only M-type stars. Based on the graph, the <em>x</em>-intercept is approximately <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"left parenthesis 158 comma 0 right parenthesis\"><mo>(</mo><mn>158</mn><mo>,</mo><mn>0</mn><mo>)</mo></math>. Therefore, if there are <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"0\"><mn>0</mn></math> K-type stars in the cluster, then there are approximately <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"158\"><mn>158</mn></math> M-type stars in the cluster.&nbsp;It&rsquo;s given that the total mass of the stars in this cluster is <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"127,882\"><mn>127,882</mn></math> quettagrams. Therefore, the estimated mass of each M-type star is approximately <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"StartFraction 127,882 Over 158 EndFraction\"><mfrac><mn>127,882</mn><mn>158</mn></mfrac></math> quettagrams, or approximately <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"809.38\"><mn>809.38</mn></math> quettagrams. Thus, of the given choices, <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"811\"><mn>811</mn></math> is the closest to the estimated mass, in quettagrams, of each M-type star in this cluster.</p>\n<p>Choice B is incorrect. This is the value closest to the estimated mass, in quettagrams, of each K-type star, not each M-type star, in this cluster.</p>\n<p>Choice C is incorrect and may result from conceptual or calculation errors.</p>\n<p>Choice D is incorrect and may result from conceptual or calculation errors.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"image_count":0,"raw_list":{"updateDate":1776362727992,"pPcc":"SAT#H","questionId":"1a1a95de","skill_cd":"H.C.","score_band_range_cd":6,"skill_desc":"Linear equations in two variables","createDate":1776362727992,"program":"SAT","primary_class_cd_desc":"Algebra","ibn":"","external_id":"43b52d01-006d-4dbc-b7a8-3187b73ccbce","primary_class_cd":"H","uId":"0f5e1577-11ab-466a-b63f-a8a2ae82c413","difficulty":"H"},"raw_detail":{"type":"mcq","stem":"<p style=\"text-align: center;\"><figure class='image'><svg height=\"285.167031pt\" version=\"1.1\" viewBox=\"0 0 304.067031 285.167031\" width=\"304.067031pt\" xmlns=\"http://www.w3.org/2000/svg\" xmlns:xlink=\"http://www.w3.org/1999/xlink\" role=\"img\" aria-label=\"Graph of a line in the x y plane with the origin labeled O. The x axis is labeled Number of M-type stars. It ranges from 0 to 160 in increments of 10, with values marked every 2 gridlines. The y axis is labeled Number of K-type stars. It ranges from 0 to 160 in increments of 10, with values marked every 2 gridlines. Refer to long description.\">\n <defs>\n  <style type=\"text/css\">\n*{stroke-linecap:butt;stroke-linejoin:round;}\n  </style>\n </defs>\n <g id=\"figure_1\">\n  <g id=\"patch_1\">\n   <path d=\"M 0 285.167031 \nL 304.067031 285.167031 \nL 304.067031 0 \nL 0 0 \nz\n\" style=\"fill:none;\"></path>\n  </g>\n  <g id=\"axes_1\">\n   <g id=\"patch_2\">\n    <path d=\"M 24.707031 260.46 \nL 296.867031 260.46 \nL 296.867031 10.98 \nL 24.707031 10.98 \nz\n\" style=\"fill:none;\"></path>\n   </g>\n   <g id=\"matplotlib.axis_1\">\n    <g id=\"text_1\">\n     <!-- Number of M-type stars -->\n     <defs>\n      <path d=\"M 53.8125 51.171875 \nQ 53.8125 57.125 53.125 59.76